-- 판정 기준값 (4-08). 연도가 바뀌면 코드는 그대로 두고 새 마이그레이션 파일로 행만 추가해요
-- 소득 기준(MEDIAN_INCOME, URBAN_WORKER_INCOME, URBAN_WORKER_AVERAGE_INCOME): 가구원 수(household_size)마다 한 행, program은 ''
-- 자산 기준(TOTAL_ASSET, CAR_VALUE): 주택 유형(program)마다 한 행, household_size는 0
-- year는 공고문이 부르는 기준 연도예요 (예: "2025년도 도시근로자 가구원수별 월평균소득" → 2025)
create table eligibility.base_values (
    id             uuid    primary key,
    kind           text    not null check (kind in ('MEDIAN_INCOME', 'URBAN_WORKER_INCOME', 'URBAN_WORKER_AVERAGE_INCOME', 'TOTAL_ASSET', 'CAR_VALUE')),
    year           integer not null,
    program        text    not null default '',
    household_size integer not null default 0,
    amount_won     bigint  not null check (amount_won > 0),
    source         text    not null,
    unique (kind, year, program, household_size)
);

-- 기준값 (2026-10-19 확인). 출처는 행마다 source에 적었어요. 공식 고시·LH 공고 원문 숫자예요
